CREATE TABLE `permission` (
  `id` varchar(50) NOT NULL COMMENT 'ID',
  `role_id` varchar(50) NOT NULL COMMENT '组ID',
  `resource_id` varchar(50) NOT NULL COMMENT '资源ID',
  `created_by` varchar(45) DEFAULT NULL COMMENT '创建人',
