  `status` int DEFAULT '1' COMMENT '状态',
  `book_id` varchar(45) DEFAULT NULL COMMENT '租户编码',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 ROW_FORMAT=DYNAMIC COMMENT='权限-组表';
